Schema Content:
type Artwork {
  artwork_id: Int!
  name: String
  nomination: [Nomination]
  type: String
}
type Festival_detail {
  chair_name: String
  festival_id: Int!
  festival_name: String
  location: String
  nomination: [Nomination]
  num_of_audience: Int
  year: Int
}
type Nomination {
  artwork: Artwork
  artwork_id: Int!
  festival_detail: Festival_detail
  festival_id: Int!
  result: String
}
input StringFilter {
  eq: String
  like: String
}
input festival_id_Filter {
  eq: Int
}
input IntFilter {
  eq: Int
  ne: Int
  gt: Int
  lt: Int
}
input NominationFilter {
  result: StringFilter
  festival_id: festival_id_Filter
}
input Festival_detailFilter{
  num_of_audience: IntFilter
}
type Query {
  artwork(artwork_id: Int!): Artwork
  artworkList: [Artwork]
  artworkPaginatedList(first: Int, after: Int): [Artwork]
  artworkUsingNomination_artwork_id_fkey(artwork_id: Int!): Artwork
  festival_detail(festival_id: Int!): Festival_detail
  filtered_festival_detail(filter: Festival_detailFilter): [Festival_detail]
  festival_detailList: [Festival_detail]
  festival_detail_by_year(year: Int!): [Festival_detail]
  festival_detailUsingNomination_festival_id_fkey(
    festival_id: Int!
  ): Festival_detail
  nomination(artwork_id: Int!, festival_id: Int!): Nomination
  nominationList: [Nomination]
  filtered_nominationList(filter: NominationFilter): [Nomination]
  nominationPaginatedList(first: Int, after: Int): [Nomination]
  nominationUsingNomination_artwork_id_fkey(artwork_id: Int!): [Nomination]
  nominationUsingNomination_festival_id_fkey(festival_id: Int!): [Nomination]
}

